import type { ChoiceType, Choices } from '..'
import type { Typed, Column } from '../Column'

export type RadioColumnType<
    TChoices extends Choices = Choices,
    Type extends ChoiceType<TChoices> = ChoiceType<TChoices>,
    Default extends Type = Type,
> = Column<Type, Default> & {
    choices?: TChoices
}

/**
 * A Column for a radio type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 *   * **choices**? - contains possible values for this field
 */
export function RadioColumn<
    const TChoices extends Choices,
    const Type extends ChoiceType<TChoices>,
    const Default extends Type,
    const C extends RadioColumnType<TChoices, Type, Default>,
>(config: C & RadioColumnType<TChoices, Type, Default>) {
    return config as Typed<Type, C>
}
